import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const LeaveRequests = () => {
  const { user } = useAuth();
  const [leaves, setLeaves] = useState([]);

  useEffect(() => {
    api.getLeaveRequests(user?.token).then(setLeaves);
  }, [user]);

  return (
    <div>
      <h2>Leave Requests</h2>
      <ul>
        {leaves.map(lr => (
          <li key={lr.id}>
            {lr.leaveType} | {lr.status} | {lr.fromDate} to {lr.toDate}
          </li>
        ))}
      </ul>
      {/* Add Create/Cancel/Edit functionality */}
    </div>
  );
};
export default LeaveRequests;
